        const writePromises = images.map((image, index) => {
            return new Promise((writeResolve, writeReject) => {
                fs.writeFile(`image${index}.png`, image, (err) => {
                    if (err) return writeReject(err);
                    writeResolve();
                });
            });
        });

        Promise.all(writePromises)
